import numpy as np
from scipy.special import betaln, comb


def beta_binomial_pmf(j, m, a, b):
    return float(comb(m, j) * np.exp(betaln(j + a, m - j + b) - betaln(a, b)))


def predictive_tail(j0, m, a, b):
    return sum(beta_binomial_pmf(j, m, a, b) for j in range(j0, m + 1))


def ppc_pvalue(y, stat, a0, b0, n_rep, seed):
    y = np.asarray(y)
    rng = np.random.default_rng(seed)
    lam = rng.gamma(a0 + y.sum(), 1 / (b0 + len(y)), n_rep)
    reps = rng.poisson(lam[:, None], (n_rep, len(y)))
    t_obs = stat(y)
    count = sum(stat(r) >= t_obs for r in reps)
    return (1 + count) / (n_rep + 1)
